private final class MaskTransformGate:@unchecked Sendable{
  let condition=NSCondition();var ready=false
  func wait(){condition.lock();while !ready{condition.wait()};condition.unlock()}
  func release(){condition.lock();ready=true;condition.broadcast();condition.unlock()}
}
final class PixelMaskTransformWorkflowTests:XCTestCase{
  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{
    var d=try CraftDocument(width:32,height:24,depth:depth),pixels=try Surface(width:32,height:24,depth:depth,fill:Pixel(0.2,0.4,0.8)),mask=try Surface(width:16,height:12,depth:depth,fill:.black);pixels.setPixel(x:7,y:6,.white)
    for y in 2..<10{for x in 3..<13{let v=Float(x+y)/24;mask.setPixel(x:x,y:y,Pixel(v,v,v))}}
    d.layers[0].content = .raster(pixels);d.layers[0].mask=mask;var p=MaskProperties();p.linked=false;d.layers[0].maskProperties=p;return d
  }
  @MainActor func testNativeMaskPreviewViewsSchemasCancelAndAllModes()async throws{
