      for mode in SelectionTransformMode.allCases{s.chooseSelectionTransformMode(mode);XCTAssertEqual(s.transformDraft?.selectionMode,mode)}
      var draft=try XCTUnwrap(s.transformDraft);draft=draft.selectionApplying(.translation(4,3));s.updateTransform(draft);await SelectedPixelTransformWorkflowTests().settle(session);XCTAssertNotNil(session.pixelPreview);XCTAssertNil(session.error);XCTAssertEqual(session.pixelPreview?.maskImage != nil,view != nil);XCTAssertEqual(s.document,source);XCTAssertTrue(s.session.undoStack.isEmpty);XCTAssertEqual(s.pixelMaskTransformState["target"] as? String,"pixelMask");let state=try JSONDecoder().decode(AutomationValue.self,from:JSONSerialization.data(withJSONObject:s.pixelMaskTransformState));XCTAssertNoThrow(try BrushAPI.merge(state,schema:PixelMaskTransformAPI.stateSchema));XCTAssertEqual(s.selectedPixelTransformState["active"] as? Bool,false);s.cancelTransform();XCTAssertTrue(session.closed);XCTAssertEqual(s.maskEditingLayerID,source.layers[0].id)
    }
  }
  @MainActor func testNativeCommitUndoActions35GuardImmediateFlipAndNative83Persistence()async throws{
    let original=try fixture(.u16),s=EditorStore(document:original);defer{s.cancelTransform();s.renderTask?.cancel()};s.selectMask(original.layers[0].id);try s.session.startActionRecording(name:"Mask");s.beginTransform();let session=try XCTUnwrap(s.selectionTransform),draft=try XCTUnwrap(s.transformDraft);s.updateTransform(draft.selectionApplying(.translation(4,3)));s.commitTransform();await session.commitTask?.value;XCTAssertNil(session.error);XCTAssertNil(s.transformDraft);XCTAssertEqual(s.session.undoStack.last?.label,"Free Transform");XCTAssertEqual(s.maskEditingLayerID,original.layers[0].id);XCTAssertEqual(s.document.layers[0].content,original.layers[0].content)
    var file=ActionLibraryFile();file.actions=[try XCTUnwrap(s.session.actionRecording?.snapshot)];let bytes=try file.encoded();XCTAssertEqual(try ActionLibraryFile.decode(bytes).version,35);var wrong=try XCTUnwrap(JSONSerialization.jsonObject(with:bytes) as? [String:Any]);wrong["version"]=34;XCTAssertThrowsError(try ActionLibraryFile.decode(JSONSerialization.data(withJSONObject:wrong)));var replay=original;try file.actions[0].apply(to:&replay);XCTAssertEqual(replay,s.document);let data=try NativeArchive.encodeChunked(s.document);XCTAssertEqual(try NativeArchive.decode(data),s.document)
    _=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,original);s.selectMask(original.layers[0].id);s.transformLayer(horizontal:true);await s.geometryTask?.value;XCTAssertNil(s.error);XCTAssertEqual(s.session.undoStack.last?.label,"Free Transform");XCTAssertEqual(s.document.layers[0].content,original.layers[0].content)
  }
