    s.beginTransform();let draft=try XCTUnwrap(s.transformDraft),flags:[NSEvent.ModifierFlags]=[.control,.command,.option,.shift];canvas.cursorLocationInView=canvas.viewPoint(draft.handles[4]);for bits in 0..<16{let f=flags.enumerated().reduce(NSEvent.ModifierFlags()){r,p in bits&(1<<p.offset) != 0 ? r.union(p.element):r};canvas.updateCursorModifiers(f);let mode=draft.selectionMode(handle:4,modifiers:f);XCTAssertEqual(canvas.toolCursor,ToolCursor.selectionTransform(mode,handle:4,flags:f,proportional:draft.proportional));XCTAssertEqual(canvas.toolCursor.native.image.size,.init(width:32,height:32))};s.cancelTransform();canvas.updateCursorModifiers([]);XCTAssertEqual(canvas.toolCursor,.arrow)
  }
  @MainActor func testHTTPThreeDepthsInterpolationProfilesAndTargetPreservationMatchNative()async throws{
