      for depth in PixelDepth.allCases{var source=try self.fixture(depth);source.workingICC=try ColorManagement.importedProfile(XCTUnwrap(CGColorSpace(name:CGColorSpace.displayP3)?.copyICCData() as Data?),depth:depth)
        for method in Resampling.allCases{s.session=EditorSession(document:source);s.selectMask(source.layers[0].id);try service.share(doc);let matrix=try ProjectiveTransform([1,0.05,2,0.05,1,1,0.002,0,1]),code=try await h.edit(service,doc,"mask.transform",["layerID":source.layers[0].id.uuidString,"matrix":matrix.values,"interpolation":method.rawValue]);XCTAssertEqual(code,200);var expected=source;try Command.transformPixelMask(.init(layerID:source.layers[0].id,matrix:matrix,interpolation:method)).apply(to:&expected);XCTAssertEqual(s.document,expected);XCTAssertEqual(s.maskEditingLayerID,source.layers[0].id);XCTAssertEqual(s.document.workingICC,source.workingICC);XCTAssertEqual(try NativeArchive.encodeChunked(s.document),try NativeArchive.encodeChunked(expected));_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source)}
      }
