      for extra:[String:Any] in [["layerID":"bad"],["matrix":[1,2]],["matrix":[0,0,0,0,0,0,0,0,0]],["matrix":[true,0,0,0,1,0,0,0,1]],["interpolation":"bad"],["unknown":1]]{let code=try await h.edit(service,doc,"mask.transform",params.merging(extra){_,b in b});XCTAssertEqual(code,400);XCTAssertEqual(s.document,source)}
      s.maskEditingLayerID=nil;let context=try await h.edit(service,doc,"mask.transform",params);XCTAssertEqual(context,422);s.selectMask(source.layers[0].id);let stale=try await h.edit(service,doc,"mask.transform",params,revision:"old");XCTAssertEqual(stale,409);s.beginTransform();let busy=try await h.edit(service,doc,"mask.transform",params);XCTAssertEqual(busy,409);s.cancelTransform()
      let gate=MaskTransformGate();defer{gate.release()};s.pixelMaskTransformPreparation={_,request in gate.wait();try Task.checkCancellation();return .transformPixelMask(request)};let task=Task{try await h.edit(service,doc,"mask.transform",params)};let until=Date().addingTimeInterval(10);while !s.geometryBusy && Date()<until{await Task.yield()};XCTAssertTrue(s.geometryBusy);service.revoke(try XCTUnwrap(service.shares.first?.id));gate.release();let code=try await task.value;XCTAssertEqual(code,409);XCTAssertEqual(s.document,source)
      let native=MaskTransformGate();defer{native.release()};s.pixelMaskTransformPreparation={_,request in native.wait();try Task.checkCancellation();return .transformPixelMask(request)};s.beginTransform();let session=try XCTUnwrap(s.selectionTransform);s.commitTransform();s.cancelTransform();native.release();await session.commitTask?.value;XCTAssertEqual(s.document,source);XCTAssertFalse(s.geometryBusy)
    }
